/**
 * Live Google Spreadsheet Sync Engine
 */
const SPREADSHEET_CSV_URL = "https://docs.google.com/spreadsheets/d/1sfypx1t696kBSgkRsuOXvxN-d_pNBuNhXAqejTjrGqQ/export?format=csv";

function getMasterBarangList() {
  try {
    const cached = localStorage.getItem('munzalan_master_barang_catalog');
    if (cached) {
      const parsed = JSON.parse(cached);
      if (Array.isArray(parsed) && parsed.length > 0) return parsed;
    }
  } catch (e) {
    console.error('Error reading cached master barang:', e);
  }
  return (typeof MASTER_BARANG_DATA !== 'undefined' && Array.isArray(MASTER_BARANG_DATA)) ? MASTER_BARANG_DATA : [];
}

async function syncMasterBarangFromSpreadsheet(showToastFlag = true) {
  const syncBtnIcon = document.getElementById('sync-sheet-icon');
  if (syncBtnIcon) syncBtnIcon.classList.add('animate-spin');

  try {
    const response = await fetch(SPREADSHEET_CSV_URL);
    if (!response.ok) throw new Error(`HTTP error! status: ${response.status}`);
    const csvText = await response.text();

    const lines = csvText.split(/\r?\n/);
    const parsedItems = [];
    let startData = false;

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i].trim();
      if (!line) continue;

      if (line.toLowerCase().includes('no.') && line.toLowerCase().includes('kode')) {
        startData = true;
        continue;
      }

      if (startData) {
        const cols = [];
        let cur = '';
        let inQuotes = false;
        for (let c = 0; c < line.length; c++) {
          const char = line[c];
          if (char === '"') {
            inQuotes = !inQuotes;
          } else if (char === ',' && !inQuotes) {
            cols.push(cur.trim());
            cur = '';
          } else {
            cur += char;
          }
        }
        cols.push(cur.trim());

        if (cols.length >= 3) {
          const noVal = parseInt(cols[0]) || (parsedItems.length + 1);
          const kodeVal = cols[1];
          const namaVal = cols[2];
          if (namaVal && namaVal !== 'dst' && !namaVal.startsWith('=')) {
            parsedItems.push({
              no: noVal,
              kode: kodeVal,
              nama: namaVal
            });
          }
        }
      }
    }

    if (parsedItems.length > 50) {
      localStorage.setItem('munzalan_master_barang_catalog', JSON.stringify(parsedItems));
      localStorage.setItem('munzalan_master_barang_last_sync', new Date().toISOString());

      if (typeof populateMasterBarangDatalist === 'function') {
        populateMasterBarangDatalist(true);
      }

      const badge = document.getElementById('catalog-count-badge');
      if (badge) badge.textContent = `${parsedItems.length}+ Katalog (Sync Live)`;

      if (showToastFlag && typeof showToast === 'function') {
        showToast(`✅ Berhasil menyinkronkan ${parsedItems.length} katalog barang langsung dari Google Spreadsheet!`, 'success');
      }
    } else {
      throw new Error('Data spreadsheet kosong atau tidak terdeteksi.');
    }
  } catch (err) {
    console.warn('Gagal sinkronisasi spreadsheet (akan menggunakan katalog lokal):', err);
    if (showToastFlag && typeof showToast === 'function') {
      showToast('⚠️ Gagal terhubung ke Google Spreadsheet live. Menggunakan katalog lokal offline.', 'warning');
    }
  } finally {
    if (syncBtnIcon) syncBtnIcon.classList.remove('animate-spin');
  }
}


